def eventualSafeNodes(V: int, adj: list) -> list:
    in_degree = [0] * V
    reverse_adj = [[] for _ in range(V)]

    for u in range(V):
        for v in adj[u]:
            reverse_adj[v].append(u)
            in_degree[u] += 1

    queue = []
    for i in range(V):
        if in_degree[i] == 0:
            queue.append(i)

    safe = [False] * V
    while queue:
        node = queue.pop(0)
        safe[node] = True
        for neighbor in reverse_adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    result = [i for i in range(V) if safe[i]]
    return result

import sys

def main():
    lines = sys.stdin.read().splitlines()
    idx = 0
    if not lines[idx]:
        idx += 1
    V = int(lines[idx])
    idx += 1
    adj = []
    for _ in range(V):
        line = lines[idx].strip()
        idx += 1
        if line == '':
            adj.append([])
        else:
            parts = list(map(int, line.split()))
            adj.append(parts)

    result = eventualSafeNodes(V, adj)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
